import{_ as t,Y as a,o as r,c as s,aq as n,H as i}from"./chunks/framework.CZHj4g6B.js";import"./chunks/theme.BZcG_oVy.js";const k=JSON.parse('{"title":"Looking Toward the Future","description":"","frontmatter":{},"headers":[],"relativePath":"en/about/future.md","filePath":"en/about/future.md"}'),l={name:"en/about/future.md"};function u(d,e,p,h,c,f){const o=a("NolebaseGitChangelog");return r(),s("div",null,[e[0]||(e[0]=n('<h1 id="looking-toward-the-future" tabindex="-1">Looking Toward the Future <a class="header-anchor" href="#looking-toward-the-future" aria-label="Permalink to &quot;Looking Toward the Future&quot;">​</a></h1><blockquote><p>The future is bright and uncertain, let us look forward to the future development space of <code>YukiHookAPI</code>.</p></blockquote><h2 id="unresolved-issues" tabindex="-1">Unresolved Issues <a class="header-anchor" href="#unresolved-issues" aria-label="Permalink to &quot;Unresolved Issues&quot;">​</a></h2><blockquote><p>Here are the unresolved issues with <code>YukiHookAPI</code>.</p></blockquote><h3 id="yukihookprefsbridge" tabindex="-1">YukiHookPrefsBridge <a class="header-anchor" href="#yukihookprefsbridge" aria-label="Permalink to &quot;YukiHookPrefsBridge&quot;">​</a></h3><p>Currently only supports LSPosed perfectly, other Xposed Framework need to downgrade the module target api.</p><p>TaiChi may not be supported at all, and TaiChi needs a lower target api to adapt on high-version systems.</p><p>Some Xposed Module developers currently choose the Hook target app self&#39;s SharedPreferences storage solution to solve the module settings sharing problem.</p><p>In the later period, the permissions of the Android system will become more and more strict, and <code>selinux</code> is a big problem currently facing, which needs to be discussed and studied.</p><div class="tip custom-block"><p class="custom-block-title">Updated on 2023.10.06</p><p>LSPosed has now experimentally launched <a href="https://github.com/libxposed" target="_blank" rel="noreferrer">Modern Xposed API</a>, which uses Service to communicate with modules, which will solve the problem of module data storage.</p><p>In order to ensure the compatibility of most modules, <strong>YukiHookAPI</strong> plans to use a customized ContentProvider to realize data exchange between the Module App and the Host App in the future, so stay tuned.</p></div><h2 id="future-plans" tabindex="-1">Future Plans <a class="header-anchor" href="#future-plans" aria-label="Permalink to &quot;Future Plans&quot;">​</a></h2><blockquote><p>Features that <code>YukiHookAPI</code> may add later are included here.</p></blockquote><h3 id="lite-version-supported-for-standalone-use" tabindex="-1">Lite Version Supported for Standalone Use <a class="header-anchor" href="#lite-version-supported-for-standalone-use" aria-label="Permalink to &quot;Lite Version Supported for Standalone Use&quot;">​</a></h3><p>If you like the Reflection API of YukiHookAPI, but your project may not need related Hook functions.</p><p>Well here is some good news for you:</p><p><s>The core Reflection API of YukiHookAPI has been decoupled into <a href="https://github.com/HighCapable/YukiReflection" target="_blank" rel="noreferrer">YukiReflection</a> project, which can now be used in any Android project.</s></p><p>The YukiReflection project has been deprecated due to many unsolved black box issues, so we no longer recommend anyone to use it. Please now migrate to the brand new design <a href="https://github.com/HighCapable/KavaRef" target="_blank" rel="noreferrer">KavaRef</a>.</p><div class="tip custom-block"><p class="custom-block-title">To be Discussed</p><p>At present, the API only supports binding to <strong>xposed_init</strong> through the automatic builder.</p><p>If you don&#39;t like the automatic builder, you must implement the module loading entry yourself.</p><p>In the future, the Lite version with only API functions will be launched according to the number of people required.</p><p>You can submit <strong>issues</strong> with us.</p></div><p>We have provided the Xposed native API listening interface, you can find or view the implementation method of the Demo <a href="./../config/xposed-using.html#native-xposed-api-events">here</a>.</p><h3 id="milestone-plan" tabindex="-1">Milestone Plan <a class="header-anchor" href="#milestone-plan" aria-label="Permalink to &quot;Milestone Plan&quot;">​</a></h3><p>The plans below have been published in <code>issues</code> on GitHub, and you can view the progress of each project.</p><p>All functions are expected to be completed in <code>2.0.0</code> version, so stay tuned.</p><ul><li><a href="https://github.com/HighCapable/YukiHookAPI/issues/49" target="_blank" rel="noreferrer">New Xposed Module Config Plan</a></li><li><a href="https://github.com/HighCapable/YukiHookAPI/issues/48" target="_blank" rel="noreferrer">New Hook Entry Class</a></li><li><s><a href="https://github.com/HighCapable/YukiHookAPI/issues/33" target="_blank" rel="noreferrer">New Hook Code Style</a></s> (Replaced by <a href="https://github.com/HighCapable/KavaRef" target="_blank" rel="noreferrer">KavaRef</a>)</li></ul>',23)),i(o)])}const g=t(l,[["render",u]]);export{k as __pageData,g as default};
